519	// CreateBill 为账户指定账期生成账单（账期不存在则幂等返回同一张）。
520	// 只能为某段订阅实际覆盖的、且已经结束的月份生成账单：开通当月计入、终止
521	// 当月（终止时刻所在月）不计入该段，完全无订阅的空档月份出账失败。
522	// 取消订阅不自动出账；终止后旧订阅覆盖的已结束月份仍可出账，使用各月当时
523	// 锁定的条件。重复调用得到同一账单；出账后金额与用量明细固定。
524	func (s *Service) CreateBill(accountID string, period Month) (Bill, error) {
525		if accountID == "" {
526			return Bill{}, invalidf("account id is empty")
527		}
528		if period.Month < time.January || period.Month > time.December {
529			return Bill{}, invalidf("invalid billing period %d-%d", period.Year, period.Month)
530		}
531		s.mu.Lock()
532		defer s.mu.Unlock()
533	
534		acc, ok := s.accounts[accountID]
535		if !ok {
536			return Bill{}, ErrAccountNotFound
537		}
538		if existing, ok := acc.bills[period]; ok {
539			return existing.bill, nil
540		}
541	
542		now := s.nowUTC()
543		// 补齐到期换套餐/取消（条件历史与分段），随后按账期取覆盖该月的订阅段中
544		// 当时适用的条件：即使已重新开通或先出新月份账单再补旧月份账单，历史账单
545		// 也不会被后来的订阅覆盖。
546		s.settleLocked(acc, now)
547	
548		if acc.sub == nil && len(acc.history) == 0 {
549			return Bill{}, ErrSubscriptionNotFound
550		}
551		if period.End().After(now) {
552			return Bill{}, ErrBillMonthNotEnded
553		}
554	
555		sub := segmentForBillingLocked(acc, period)
556		if sub == nil {
557			// 早于首段开通，或处于两段订阅之间的空档。
558			return Bill{}, ErrBillBeforeSubscription
559		}
560	
561		terms := termsForPeriod(sub, period)
562		bill, err := buildBill(accountID, period, terms, acc.usage[period])
563		if err != nil {
564			return Bill{}, err
565		}
566		acc.bills[period] = &billRecord{bill: bill}
567		return bill, nil
568	}
